content:
{
  "intent": "将用户明确陈述的花生过敏这一持久健康事实保存到本人记忆",
  "confidence": 0.97,
  "required_tools": ["memory.set"],
  "task_steps": [
    "识别为关于请求者本人的明确、持久健康事实，归属 me 命名空间",
    "以稳定点分键 me.allergy.peanut 写入，值为陈述句，避免记录临时情绪或猜测",
    "无需检索房间备忘或其他工具"
  ],
  "final_response_plan": "调用 memory.set 保存过敏事实；回复中确认已记住，并说明之后在饮食相关建议中会据此规避花生。",
  "final_response_text": "好的，我记下了：你对花生过敏。之后涉及饮食、点餐或聚会安排时，我会据此提醒规避花生及可能含花生的食品。",
  "tool_inputs": {
    "memory.set": {
      "key": "me.allergy.peanut",
      "value": "小林对花生过敏，饮食与点餐需规避花生及含花生制品。",
      "scope": "me",
      "source": "用户自述"
    }
  }
}
